var sec = await figma.getNodeByIdAsync("67:75");
if (!sec) throw new Error("PCB_NOT_FOUND 67:75");
var page = sec.parent; while (page && page.type !== 'PAGE') page = page.parent;
var out = { sectionId: sec.id, sectionName: String(sec.name), sectionType: sec.type, page: page ? { id: page.id, name: String(page.name) } : null, templates: [], labels: [] };
for (var i = 0; i < sec.children.length; i++) {
  var t = sec.children[i];
  if (t.type === 'TEXT') { out.labels.push({ id: t.id, text: String(t.characters) }); continue; }
  if (t.type !== 'FRAME') continue;
  var ob = t.absoluteBoundingBox;
  var rec = { id: t.id, name: String(t.name), width: t.width, height: t.height, layers: [] };
  for (var j = 0; j < t.children.length; j++) {
    var L = t.children[j];
    var lr = { id: L.id, name: String(L.name), type: L.type, visible: L.visible, shapes: [] };
    if (L.type === 'TEXT') lr.text = String(L.characters);
    var shapesFrame = ('children' in L) ? L.children.filter(function (c) { return c.name === 'Shapes'; })[0] : null;
    if (shapesFrame) {
      for (var k = 0; k < shapesFrame.children.length; k++) {
        var s = shapesFrame.children[k], b = s.absoluteBoundingBox;
        lr.shapes.push({ id: s.id, name: String(s.name), type: s.type, visible: s.visible, rect: b ? { x: Math.round((b.x - ob.x) * 100) / 100, y: Math.round((b.y - ob.y) * 100) / 100, w: Math.round(b.width * 100) / 100, h: Math.round(b.height * 100) / 100 } : null });
      }
    }
    rec.layers.push(lr);
  }
  out.templates.push(rec);
}
return out;
